#include <bits/stdc++.h>
using namespace std;

#define rep(i, n) for(int i = 0; i < n; ++i)
#define rep3(i, a, b) for(int i = a; i >= b; i--)

int main(void) {
	int n;
	int m[2];

	bitset<3600001> a[2001];
	int b[2000];
	char c[4] = { 'L','U','D','R' };

	bool v = true;
	int x, y;
	string ans;

	cin >> n >> x >> y;
	m[0] = x + y;
	m[1] = x - y;
	x = 0;
	rep(i, n) {
		cin >> b[i];
		x += b[i];
	}
	rep(i, 2)if (abs(m[i]) > abs(x))v = false;
	rep(i, 2)if ((m[i] + x) % 2 != 0)v = false;
	if (!v) {
		cout << "No" << endl;
		return 0;
	}
	rep(i, 2)m[i] = (m[i] + x) / 2;
	a[0][0] = true;
	rep(i, 2000)a[i + 1] = a[i] | (a[i] << b[i]);
	if ((!a[n][m[0]]) || (!a[n][m[1]])) {
		cout << "No" << endl;
		return 0;
	}
	rep3(i, n - 1, 0) {
		x = 0;
		rep(j, 2) {
			if (!a[i][m[j]]) {
				m[j] -= b[i];
				x += (1 << j);
			}
		}
		ans = c[x] + ans;
	}
	cout << "Yes" << endl;
	cout << ans << endl;

	return 0;
}
